import{_ as t,o as a,c as n,a2 as r}from"./chunks/framework.hw3Av5Vn.js";const y=JSON.parse('{"title":"Folk","description":"","frontmatter":{},"headers":[],"relativePath":"demos/FOLK.md","filePath":"demos/FOLK.md"}'),s={name:"demos/FOLK.md"};function l(o,e,h,c,i,d){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="folk" tabindex="-1">Folk <a class="header-anchor" href="#folk" aria-label="Permalink to &quot;Folk&quot;">​</a></h1><p>The demo songs in the folk style. Each is described below, with the features it uses; <a href="./../DEMOS">About Demos</a> lists every demo.</p><ul><li><a href="#arrangement_shanty">Few Patterns</a>: <code>20_arrangement_shanty.yml</code></li><li><a href="#classic_strum">Strum</a>: <code>13_classic_strum.yml</code></li><li><a href="#complex_gifts_chain">Chains</a>: <code>17_complex_gifts_chain.yml</code></li><li><a href="#hocket_shanty">Hocketing</a>: <code>19_hocket_shanty.yml</code></li><li><a href="#secret_chord">Hallelujah Chords</a>: <code>secret_chord.yml</code></li></ul><p><a id="arrangement_shanty"></a></p><h2 id="few-patterns-20-arrangement-shanty-yml" tabindex="-1">Few Patterns: <code>20_arrangement_shanty.yml</code> <a class="header-anchor" href="#few-patterns-20-arrangement-shanty-yml" aria-label="Permalink to &quot;Few Patterns: `20_arrangement_shanty.yml`&quot;">​</a></h2><p>The Wellerman again, with eight parts built from only four note patterns. The harmony is the melody patterns transposed on its track, the bass grabs the roots of the pad&#39;s chords, and a counter-line grabs the melody in its own rhythm. Read this one to see how to set up a song so that changing one pattern changes every part that follows it.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/20_arrangement_shanty.yml" target="_blank" rel="noreferrer"><code>examples/learning/20_arrangement_shanty.yml</code></a> · A minor · 100 BPM · 2:34 · 8 scenes · 8 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">arps</th><th style="text-align:center;">chains</th><th style="text-align:center;">grabs</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="classic_strum"></a></p><h2 id="strum-13-classic-strum-yml" tabindex="-1">Strum: <code>13_classic_strum.yml</code> <a class="header-anchor" href="#strum-13-classic-strum-yml" aria-label="Permalink to &quot;Strum: `13_classic_strum.yml`&quot;">​</a></h2><p>An acoustic folk song in G major whose guitar chords are strummed as a hand crosses the strings, down on the beats and up between them, compared scene by scene: struck all at once, strummed tight, normal, with the full acoustic setting of fade, loose timing and light upstrokes, and rolled like a harp.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/13_classic_strum.yml" target="_blank" rel="noreferrer"><code>examples/learning/13_classic_strum.yml</code></a> · G major · 92 BPM · 2:52 · 9 scenes · 2 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th><th style="text-align:center;">strum</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="complex_gifts_chain"></a></p><h2 id="chains-17-complex-gifts-chain-yml" tabindex="-1">Chains: <code>17_complex_gifts_chain.yml</code> <a class="header-anchor" href="#chains-17-complex-gifts-chain-yml" aria-label="Permalink to &quot;Chains: `17_complex_gifts_chain.yml`&quot;">​</a></h2><p>Simple Gifts on a single track, growing from the plain tune into triads, then synthwave, then happy metal, using only five patterns and a chain for each scene. The demo shows that a chain runs its steps in order, so an arpeggiator followed by an AutoRatchet sounds different from the other way round.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/17_complex_gifts_chain.yml" target="_blank" rel="noreferrer"><code>examples/learning/17_complex_gifts_chain.yml</code></a> · A major · 120 BPM · 2:40 · 10 scenes · 1 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">arps</th><th style="text-align:center;">ratchets</th><th style="text-align:center;">chains</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="hocket_shanty"></a></p><h2 id="hocketing-19-hocket-shanty-yml" tabindex="-1">Hocketing: <code>19_hocket_shanty.yml</code> <a class="header-anchor" href="#hocketing-19-hocket-shanty-yml" aria-label="Permalink to &quot;Hocketing: `19_hocket_shanty.yml`&quot;">​</a></h2><p>The Wellerman, held by a muted track called SILENT melody, with up to four voices taking turns at its notes, one note each, through a Hocket generator that names the melody&#39;s track as its source. That&#39;s called hocketing. One voice plays every note, two alternate, and four each play every fourth note; each voice has a sound of its own, flute, clarinet, oboe and violin, to hear the tune pass between them.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/19_hocket_shanty.yml" target="_blank" rel="noreferrer"><code>examples/learning/19_hocket_shanty.yml</code></a> · A minor · 100 BPM · 2:14 · 7 scenes · 5 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chains</th><th style="text-align:center;">hocket</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="secret_chord"></a></p><h2 id="hallelujah-chords-secret-chord-yml" tabindex="-1">Hallelujah Chords: <code>secret_chord.yml</code> <a class="header-anchor" href="#hallelujah-chords-secret-chord-yml" aria-label="Permalink to &quot;Hallelujah Chords: `secret_chord.yml`&quot;">​</a></h2><p>Leonard Cohen&#39;s chords for Hallelujah in 6/8, played by a piano, a bass and strings through Progression chains, under a cello melody of its own. The scale&#39;s own chord on 3, E minor, stands where the song has E major.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/folk/secret_chord.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/folk/secret_chord.yml</code></a> · C major · 84 BPM · 3:00 · 8 scenes · 5 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table>',28)])])}const g=t(s,[["render",l]]);export{y as __pageData,g as default};
